// You can rotate the camera with the mouse, change the focus distance
// by clicking on a surface or by using LEFT and RIGHT keys, and moving
// the camera back and forward by using DOWN and UP keys.
// The shader calculates image noise level per fragment.
// When the noise level threshold is reached, the shader stops refining
// that fragment.
// The shader adjusts the number of raytracing passes based on the
// framerate.
// You can change the framerate limit in the Common tab.

// Uncomment the line below to show the noise evaluation debug overlay.
// #define NOISE_OVERLAY

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec4 buf = read_buffer(iChannel0, ivec2(fragCoord));
    vec3 color = buf.rgb;
    color = tonemap(color, gamma, exposure);
    color = clamp(color, vec3(0), vec3(1));

#ifdef NOISE_OVERLAY
    float M = buf.a;
    int num_passes = get_pass_index(iChannel1) + get_num_passes_per_frame(iChannel1);
    float SE = clamp(standard_error(M, num_passes), noise_threshold, 1.);
    const float a = noise_threshold * 0.3;
    float f = a * (1. - SE) / (noise_threshold - 1.) / (noise_threshold - a - SE); // https://www.desmos.com/calculator/etcxxjh391
    color = mix((rgb2grayscale(color) + 0.02) / 1.02 * mix(vec3(1, 0, 0), vec3(0, 1, 0), f), color, float(below_threshold(M, num_passes)));
    //color = mix(vec3(1, 0, 0), vec3(0, 1, 0), f);
#endif

    fragColor = vec4(linear2gamma_wgrgb(color), 1.);
}

// Set to your screen refresh rate
const float max_framerate = 60.;

// Scene parameters
const float middle_sphere_r = 1.0;
const float satellite_sphere_r = middle_sphere_r / 2.5;
const float sphere_offset = middle_sphere_r * 1.2 + satellite_sphere_r;

// Materials parameters
const float air_ior = 1.0;
const float glass_ior = 1.522;
const float glass_ior_coeff = 0.00459;
