const vec3 red             = vec3(0.15, 0.005, 0.005);
const vec3 green           = vec3(0.01, 0.11, 0.01);
const vec3 orange          = vec3(0.2, 0.03, 0.01);
const vec3 high_iron_glass = vec3(0.8, 0.9, 0.8);
