// Light parameters
const float skybox_contrast = 4.;
const float skybox_intensity = 1.0;
const float skybox_saturation = 1.5;

// Camera parameters
const float fov = radians(25.); // Horizontal field of view
const float init_camera_distance = middle_sphere_r * 5.;
const vec2 camera_orientation_offset = radians(vec2(75, 5.));
const vec3 camera_pos_offset = vec3(0);
const float camera_rotation_speed_coeff = 3.0;
const float aperture_size = middle_sphere_r * 0.25; // The bigger the aperture, the bigger the DOF effect.
const float init_focus_distance = init_camera_distance - sphere_offset;
const float exposure = 5.;
const float gamma = 20.;

// Ray tracing parameters
const float distance_limit = 1e3;
const float surface_offset = 1e-4; // New ray surface offset.
const int max_passes_per_frame = 128;
const int min_passes_per_frame = 1;
const int rays_stack_size = 8;
const float ray_importance_threshold = 1e-5;
const int reflections_num_limit = 64;
const int refractions_num_limit = 64;
// Noise added to rays to smooth out the result. Value in the range of [0:1] is within a pixel. Acts like antialiasing.
const float ray_noise_coeff = 1.0;

// Result noise level detection parameters
const float noise_threshold = 5e-3;
const float noise_sample_r = 1.0;
const int min_passes = 200;

// Data storage locations
const int pass_index_id = 0;
const int num_passes_per_frame_id = 1;
const int mouse_id = 2;
const int orientation_id = 3;
const int resolution_id = 4;
const int focus_distance_id = 5;
const int camera_distance_id = 6;

struct sphere_t
{
    vec3 pos;
    vec3 color;
    float r;
};

