    sphere_t(vec3(0), high_iron_glass, middle_sphere_r),
    sphere_t(vec3(cos(pentagon_angle * 0.5), 0, sin(pentagon_angle * 0.5)) * sphere_offset, high_iron_glass, satellite_sphere_r),
    sphere_t(vec3(cos(pentagon_angle * 1.5), 0, sin(pentagon_angle * 1.5)) * sphere_offset, high_iron_glass,   satellite_sphere_r),
    sphere_t(vec3(cos(pentagon_angle * 2.5), 0, sin(pentagon_angle * 2.5)) * sphere_offset, high_iron_glass,    satellite_sphere_r),
