// https://www.shadertoy.com/view/ttc3zr
uint murmurHash14(uvec4 src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y; h *= M; h ^= src.z; h *= M; h ^= src.w;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// 1 output, 4 inputs
float hash14(vec4 src) {
    uint h = murmurHash14(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}

uvec2 murmurHash24(uvec4 src) {
    const uint M = 0x5bd1e995u;
    uvec2 h = uvec2(1190494759u, 2147483647u);
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y; h *= M; h ^= src.z; h *= M; h ^= src.w;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

// 2 outputs, 4 inputs
vec2 hash24(vec4 src) {
    uvec2 h = murmurHash24(floatBitsToUint(src));
    return uintBitsToFloat(h & 0x007fffffu | 0x3f800000u) - 1.0;
}

float noise(const vec2 uv, const int frame, inout int seed)
{
    return hash14(vec4(uv, vec2(frame + 1, ++seed)));
}

vec2 noise2(const vec2 uv, const int frame, inout int seed)
{
    return hash24(vec4(uv, vec2(frame + 1, ++seed)));
}

// https://www.desmos.com/calculator/vxmtgd7kvz
vec3 tonemap(const vec3 x, const float a, const float b)
{
    return a != 0. ? x * (1. + 1. / a) / (x + 1. / (a * b)) : x * b;
}

float rgb2grayscale(const vec3 rgb)
{
    const vec3 rgb_weights = vec3(0.3, 0.59, 0.11);
    return dot(rgb, rgb_weights);
}

vec3 saturation(const vec3 color, const float a)
{
    float avg = rgb2grayscale(color);
    return max(mix(vec3(avg), color, a), 0.0);
}

vec3 linear2gamma_wgrgb(const vec3 x)
{
    return pow(x, vec3(1.0/2.2));
}

// Apply sRGB gamma correction to a linear value.
vec3 srgb_linear2gamma(const vec3 x)
{
    return mix(12.92 * x, 1.055 * pow(x, vec3(1./2.4)) - 0.055, greaterThan(x, vec3(0.0031308)));
} 

vec3 srgb_gamma2linear(const vec3 x)
{
    return mix(x * 0.0774, pow((x + 0.055) * 0.9479, vec3(2.4)), greaterThan(x, vec3(0.04045)));
}

#define read_buffer(buffer, uv) texelFetch(buffer, uv, 0)

int get_num_passes_per_frame(const sampler2D buf_a)
{
    return int(read_buffer(buf_a, ivec2(num_passes_per_frame_id, 0)).r);
}

int get_pass_index(const sampler2D buf_a)
{
    return int(read_buffer(buf_a, ivec2(pass_index_id, 0)).r);
}

vec2 get_resolution(const sampler2D buf_a)
{
    return read_buffer(buf_a, ivec2(resolution_id, 0)).xy;
}

float get_camera_distance(const sampler2D buf_a)
{
    return read_buffer(buf_a, ivec2(camera_distance_id, 0)).r;
}

float standard_error(const float M, const int pass)
{
    return sqrt(M / (float(pass - 1) * float(pass)));
}

bool below_threshold(float M, const int pass)
{
    return pass < min_passes ? false : standard_error(M, pass) < noise_threshold;
}

bool sphere_hit(const vec2 t)
{
    return t[1] > surface_offset; // The sphere is not behind
}

vec2 sphere_intersection(const ray_t ray, const sphere_t sphere)
{
    vec3 r_min_o = ray.pos - sphere.pos;
    float b = 2.0 * dot(r_min_o, ray.dir);
    float c = dot(r_min_o, ray.pos) - dot(r_min_o, sphere.pos) - sphere.r * sphere.r;
    float d = b * b - 4.0 * c;
    if(d <= 0.0)
    {
        // The ray missed the sphere.
        return vec2(-1.0);
    }

    // First intersection
    float t0 = (-b - sqrt(d)) * 0.5;
    // Second intersection
    float t1 = (-b + sqrt(d)) * 0.5;

    return vec2(t0, t1);
}

intersection_t build_intersection(const ray_t ray, const sphere_t sphere, const vec2 t)
{
    intersection_t intersection;
    intersection.inside = t[0] < surface_offset;
    intersection.pos = ray.pos + ray.dir * t[int(intersection.inside)];
    intersection.normal = normalize(sphere.pos - intersection.pos) * float(int(intersection.inside) * 2 - 1);
    intersection.color = intersection.inside ? pow(sphere.color, vec3(t[1] - t[0])) : vec3(1.);
    return intersection;
}

bool find_closest_intersection(const ray_t ray, out intersection_t intersection)
{
    // Find the closest sphere the ray intersects by iterating through all spheres.
    float sphere_distance = distance_limit;

    int sphere_hit_index = -1;
    vec2 t;
    for(int i = 0; i < spheres.length(); ++i)
    {
        vec2 t_tmp = sphere_intersection(ray, spheres[i]);
        if(sphere_hit(t_tmp) && sphere_distance > t_tmp[1])
        {
                // This sphere is closer to the ray origin.
                sphere_hit_index = i;
                sphere_distance = t_tmp[1];
                t = t_tmp;
        }
    }

    if(sphere_hit_index > -1)
    {
        intersection = build_intersection(ray, spheres[sphere_hit_index], t);
        return true;
    }

    return false;
}

camera_t get_camera(const vec2 resolution, const sampler2D data_channel)
{
    camera_t cam;
    cam.fov_ctg = 1.0 / tan(fov);
    cam.ratio = resolution.x / resolution.y;

    vec2 orientation = read_buffer(data_channel, ivec2(orientation_id, 0)).xy;

    // Define and rotate basis vectors vertically.
    cam.right = vec3(cos(orientation.x), 0, sin(orientation.x));
    cam.forward = vec3(-sin(orientation.x), 0, cos(orientation.x));
    cam.up = vec3(0, cos(orientation.y), 0) + cam.forward * sin(orientation.y);
    cam.forward = cam.forward * cos(orientation.y) + vec3(0, -sin(orientation.y), 0);

    // Camera is always looking at the first sphere.
    cam.pos = camera_pos_offset - cam.forward * get_camera_distance(data_channel);
    return cam;
}

// State.

#define KEY_LEFT 37
#define KEY_UP 38
#define KEY_RIGHT 39
#define KEY_DOWN 40

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 coord = ivec2(fragCoord);    
    if(coord.y > 0)
    {
        return;
    }

    bool mb = iMouse.z > 0.0;
    vec4 prev_frame = read_buffer(iChannel0, coord);

    bool up_pressed = bool(texelFetch(iChannel1, ivec2(KEY_UP, 0), 0).x);
    bool down_pressed = bool(texelFetch(iChannel1, ivec2(KEY_DOWN, 0), 0).x);
    bool left_pressed = bool(texelFetch(iChannel1, ivec2(KEY_LEFT, 0), 0).x);
    bool right_pressed = bool(texelFetch(iChannel1, ivec2(KEY_RIGHT, 0), 0).x);
    bool key_pressed = up_pressed || down_pressed || left_pressed || right_pressed;

    fragColor = vec4(0);
    switch(coord.x)
    {
    case pass_index_id:
        vec2 prev_res = get_resolution(iChannel0);
        if(mb || prev_res != iResolution.xy || key_pressed || iFrame == 0)
        {
            fragColor = vec4(0);
        }
        else
        {
            fragColor = vec4(round(prev_frame.x + float(get_num_passes_per_frame(iChannel0))));
        }
        break;
    case num_passes_per_frame_id:
        const float scale_factor = 1.02;
        if(get_pass_index(iChannel0) < 60 || mb)
        {
            fragColor = vec4(min_passes_per_frame);
        }
        else if(iTimeDelta <= 1. / max_framerate)
        {
            fragColor = vec4(min(prev_frame.x * scale_factor, float(max_passes_per_frame)));
        }
        else if(iTimeDelta > 2. / max_framerate)
        {
            fragColor = vec4(max(prev_frame.x / scale_factor, float(min_passes_per_frame)));
        }
        else
        {
            fragColor = prev_frame;
        }
        break;
    case mouse_id:
        fragColor = iMouse;
        break;
    case orientation_id:
        if(iFrame == 0)
        {
            fragColor = vec4(camera_orientation_offset, 0, 0);
        }
        else
        {
            vec2 pos_delta = vec2(0);
            vec4 prev_mouse = read_buffer(iChannel0, ivec2(mouse_id, 0));
            if(prev_mouse.z > 0.0 && iMouse.z > 0.0)
            {
                pos_delta = iMouse.xy - prev_mouse.xy;
            }
            vec2 new_orientation = prev_frame.xy - pos_delta / iResolution.y * camera_rotation_speed_coeff;
            if(new_orientation.x > radians(360.))
            {
                new_orientation.x -= radians(360.);
            }
            else if(new_orientation.x < 0.0)
            {
                new_orientation.x += radians(360.);
            }

            new_orientation.y = clamp(new_orientation.y, radians(-90.), radians(90.));

            fragColor = vec4(new_orientation, 0, 0);
        }
        break;
    case resolution_id:
        fragColor = vec4(iResolution, 0);
        break;
    case focus_distance_id:
        if(iFrame == 0)
        {
            fragColor = vec4(init_focus_distance);
        }
        else
        {
            if(key_pressed)
            {
                float dir = (float(right_pressed) - float(left_pressed)) * iTimeDelta * 5.;
                fragColor = max(prev_frame * pow(1.1, dir), 0.1);
            }
            else if(iMouse.z > 0.0)
            {
                camera_t cam = get_camera(iResolution.xy, iChannel0);

                vec2 normalized_coords = iMouse.xy / iResolution.xy * 2.0 - 1.0;
                vec3 ray_dir = cam.forward * cam.fov_ctg +
                               cam.right * normalized_coords.x +
                               cam.up * normalized_coords.y / cam.ratio;

                ray_t ray = ray_t(cam.pos, normalize(ray_dir), vec3(1.0));
                intersection_t intersection;
                bool index = find_closest_intersection(ray, intersection);
                if(index)
                {
                    float distance = dot(cam.forward, intersection.pos - cam.pos);
                    fragColor = vec4(distance);
                }
                else
                {
                    fragColor = vec4(distance_limit);
                }
            }
            else
            {
                fragColor = prev_frame;
            }
        }
        break;
    case camera_distance_id:
        if(iFrame == 0)
        {
            fragColor = vec4(init_camera_distance);
            break;
        }
        float dir = (float(down_pressed) - float(up_pressed)) * iTimeDelta * 5.;
        fragColor = max(prev_frame * pow(1.1, dir), 0.1);
        break;
    }
}

