const float wl_min = 390.0;
const float wl_max = 730.0;
const int cie_sample_num = 69;

vec3 wl2wgrgb_cie2006(const float wl)
{
    float x = clamp((wl - wl_min) / (wl_max - wl_min), 0., 1.) * float(cie_sample_num - 1);
    int index1 = int(x);
    int index2 = min(index1 + 1, cie_sample_num - 1);
    x -= float(index1);
    return mix(cie2006_2e_wgrgb(index1), cie2006_2e_wgrgb(index2), x);
}

float fresnel_schlick(const float cos_theta, const float ior1, const float ior2)
{
    float r0 = (ior1 - ior2) / (ior1 + ior2);
    r0 = r0 * r0;
    float a = 1.0 - cos_theta;
    float a5 = a * a;
    a5 *= a5 * a;
    return r0 + (1.0 - r0) * a5;
}

vec3 reflect_ray(const vec3 v, const vec3 n)
{
    return normalize(reflect(v, n));
}

vec3 sky_box(const vec3 v)
{
    vec3 linear = srgb_gamma2linear(textureLod(iChannel0, v, 0.0).rgb);

    // Apply fake hdr effect by increasing contrast and scaling the values.
    vec3 hdr = pow(saturation(linear, skybox_saturation), vec3(skybox_contrast)) * skybox_intensity;
    return hdr;
}

// https://en.wikipedia.org/wiki/Cauchy%27s_equation
float wl2ior(const float w, const float a, const float b)
{
    return a + b / (w * w);
}

ray_t init_ray(const camera_t cam, const vec3 color)
{
    vec2 uv = gl_FragCoord.xy / iResolution.xy;

    // Shape of the noise defines the bokeh shape. In this case it's a circle.
    vec2 square_noise = noise2(uv, iFrame, seed);
    vec2 dof_noise = vec2(sqrt(square_noise.x) * 0.5, square_noise.y * radians(360.));
    vec3 dof = (cam.right * cos(dof_noise.y) + cam.up * sin(dof_noise.y)) * dof_noise.x * aperture_size;

    vec2 pixel_noise = (noise2(uv, iFrame, seed) - 0.5) / iResolution.xy * ray_noise_coeff;
    vec2 normalized_coords = (uv + pixel_noise) * 2.0 - 1.0;
    // Initial ray direction based on the normalized fragment coordinates and camera orientation.
    vec3 ray_dir = cam.forward +
                   cam.right * normalized_coords.x / cam.fov_ctg +
                   cam.up * normalized_coords.y / (cam.ratio * cam.fov_ctg);
    ray_dir *= read_buffer(iChannel1, ivec2(focus_distance_id, 0)).x;
    ray_dir += dof;

    return ray_t(cam.pos - dof, normalize(ray_dir), color);
}

vec4 get_prev_result()
{
    return read_buffer(iChannel2, ivec2(gl_FragCoord.xy));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int pass_index = get_pass_index(iChannel1);
    ivec2 int_frag_coord = ivec2(fragCoord);
    float M = pass_index == 0 ? 1. : 0.;
    float gaussian_volume = 0.;
    vec4 prev = pass_index == 0 ? vec4(0) : get_prev_result();

    if(pass_index > 1)
    {
        int i_min = int(floor(max(float(int_frag_coord.x) - noise_sample_r, 0.))) - int_frag_coord.x;
        int i_max = int(ceil(min(float(int_frag_coord.x) + noise_sample_r, iResolution.x - 1.))) - int_frag_coord.x;

        int j_min = int(floor(max(float(int_frag_coord.y) - noise_sample_r, 0.))) - int_frag_coord.y;
        int j_max = int(ceil(min(float(int_frag_coord.y) + noise_sample_r, iResolution.y - 1.))) - int_frag_coord.y;

        for(int j = j_min; j <= j_max; ++j)
        {
            for(int i = i_min; i <= i_max; ++i)
            {
                ivec2 coords = int_frag_coord + ivec2(i, j);
                float value = read_buffer(iChannel2, coords).a;
                float g = exp(-4. / float(noise_sample_r * noise_sample_r) * float(i * i)) *
                          exp(-4. / float(noise_sample_r * noise_sample_r) * float(j * j));
                M += value * g;
                gaussian_volume += g;
            }
        }

        M /= gaussian_volume;
    }

    if(below_threshold(M, pass_index))
    {
        fragColor = vec4(prev.rgb, M);
        return;
    }

    vec3 mean = prev.rgb;

    vec2 uv = fragCoord / iResolution.xy;

    camera_t cam = get_camera(iResolution.xy, iChannel1);

    ray_t rays_stack[rays_stack_size + 2];

    int num_passes_per_frame = get_num_passes_per_frame(iChannel1);

    for(int pass = 0; pass < num_passes_per_frame; ++pass, ++pass_index)
    {
        // The final color is accumulated with rays interacting the scene.
        vec3 result = vec3(0);

        float wl = mix(wl_min, wl_max, noise(uv, iFrame, seed));
        vec3 rgb = wl2wgrgb_cie2006(wl);

        float ior = wl2ior(wl * 0.001, glass_ior, glass_ior_coeff);

        int num_reflections = 0;
        int num_refractions = 0;

        rays_stack[0] = init_ray(cam, rgb);
        int num_rays = 1;

        while(num_rays > 0)
        {
            // Get the next ray.
            --num_rays;
            ray_t ray = rays_stack[num_rays];

            intersection_t intersection;
            if(!find_closest_intersection(ray, intersection))
            {
                // The ray doesn't intersect any surfaces, so it hits the skybox.
                result += sky_box(ray.dir) * ray.color;
            }
            else if(num_rays > rays_stack_size)
            {
                // We can't emit new rays.
                continue;
            }
            else
            {
                float transition_ior[2];
                transition_ior[int(intersection.inside)] = air_ior;
                transition_ior[int(!intersection.inside)] = ior;

                vec3 next_color = ray.color * intersection.color;

                vec3 refraction = refract(ray.dir, intersection.normal, transition_ior[0] / transition_ior[1]);
                bool tir = vec3(0.0) == refraction;

                if(!tir && num_refractions < refractions_num_limit)
                {
                    refraction = normalize(refraction);
                    float fresnel_refraction = 1.0 - fresnel_schlick(dot(-intersection.normal, refraction), transition_ior[1], transition_ior[0]);
                    vec3 next_color_refraction = next_color * fresnel_refraction;

                    if(rgb2grayscale(next_color_refraction) >= ray_importance_threshold)
                    {
                        // Emit refraction ray (add it to the list).
                        rays_stack[num_rays] = ray_t(intersection.pos, refraction, next_color_refraction);
                        ++num_rays;
                        ++num_refractions;
                    }
                }

                bool skip_reflection = tir && intersection.inside;
                if(!skip_reflection && num_reflections < reflections_num_limit)
                {
                    float fresnel_reflection = tir ? 1.0 : fresnel_schlick(dot(intersection.normal, -ray.dir), transition_ior[0], transition_ior[1]);
                    vec3 next_color_reflection = next_color * fresnel_reflection;
                    if(rgb2grayscale(next_color_reflection) >= ray_importance_threshold)
                    {
                        // Emit reflection ray (add it to the list).
                        vec3 reflection = reflect_ray(ray.dir, intersection.normal);
                        rays_stack[num_rays] = ray_t(intersection.pos, reflection, next_color_reflection);
                        ++num_rays;
                        ++num_reflections;
                    }
                }
            }
        }

        const float c = 0.3;
        vec3 prev_mean_t = tonemap(mean, gamma, exposure);
        prev_mean_t = clamp(prev_mean_t, vec3(0), vec3(1));
        prev_mean_t = pow(prev_mean_t, vec3(c));

        float current_pass_num = float(pass_index + 1);
        mean += (result - mean) / current_pass_num;

        vec3 new_mean_t = tonemap(mean, gamma, exposure);
        new_mean_t = clamp(new_mean_t, vec3(0), vec3(1));
        new_mean_t = pow(new_mean_t, vec3(c));

        vec3 new_t = (new_mean_t - prev_mean_t) * current_pass_num + prev_mean_t;

        M += pass_index > 0 ? rgb2grayscale((new_t - prev_mean_t) * (new_t - new_mean_t)) : 0.;
    }

    fragColor = vec4(mean, M);
}
